-- ------------------------------------------------------------------------------------
-- AUTOGENERATED HYPRLAND CONFIG.
-- EDIT THIS CONFIG ACCORDING TO THE WIKI INSTRUCTIONS.
-- ------------------------------------------------------------------------------------

-- This is an example Hyprland config file.
-- Refer to the wiki for more information.
-- https://wiki.hypr.land/Configuring/

-- Please note not all available settings / options are set here.
-- For a full list, see the wiki

-- You can split this configuration into multiple files
-- Create your files separately and then link them to this file like this:
-- source = ~/.config/hypr/myColors.conf


-- -----------------------------------
-- ------ ENVIRONMENT VARIABLES ------
-- -----------------------------------

-- See https://wiki.hypr.land/Configuring/Environment-variables/

hl.env("XDG_SESSION_TYPE", "wayland")
hl.env("QT_QPA_PLATFORM", "wayland;xcb")
hl.env("GDK_BACKEND", "wayland,x11,*")
hl.env("QT_QPA_PLATFORMTHEME", "qt6ct")

hl.env("HYPRCURSOR_THEME", "theme_minecraft-hypr")
hl.env("HYPRCURSOR_SIZE", "24")
hl.env("XCURSOR_THEME", "minecraft-theme") -- Keep as fallback for GTK apps
hl.env("XCURSOR_SIZE", "24")

-- Nvidia drivers
hl.env("LIBVA_DRIVER_NAME", "nvidia")
hl.env("__GLX_VENDOR_LIBRARY_NAME", "nvidia")
-- hl.env("__GL_GSYNC_ALLOWED", "0")
-- hl.env("__GL_VRR_ALLOWED", "0")
hl.env("GBM_BACKEND", "nvidia-drm")

-- Additional
hl.env("MANGOHUD_CONFIGFILE", "$HOME/.config/MangoHud/MangoHud.conf")


-- ----------------------
-- ------ MONITORS ------
-- ----------------------

-- See https://wiki.hypr.land/Configuring/Monitors/

hl.monitor({
  output = "",
  mode = "highrr",
  position = "auto",
  scale = "auto",
})


-- -------------------------
-- ------ MY PROGRAMS ------
-- -------------------------

-- See https://wiki.hypr.land/Configuring/Keywords/

-- Set programs that you use
local terminal = "kitty bash"
local fileManager = "dolphin"
local menu = "wofi --show=drun"
local browser = "chromium"


-- -----------------------
-- ------ AUTOSTART ------
-- -----------------------

hl.on("hyprland.start", function()
  -- System
  hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
  hl.exec_cmd("systemctl --user import-environment WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
  hl.exec_cmd("systemctl --user start hyprpolkitagent")

  -- Programs 
  hl.exec_cmd("nm-applet --indicator")
  hl.exec_cmd("blueman-applet")
  hl.exec_cmd("pasystray")
  hl.exec_cmd("wl-paste --type text --watch cliphist store")
  hl.exec_cmd("awww-daemon")
  hl.exec_cmd("swaync")
  hl.exec_cmd("swaync-client -df")
  hl.exec_cmd("swayosd-server -s ~/.config/swayosd/style.css")
  hl.exec_cmd("otd-daemon")
  hl.exec_cmd("sleep 1 && waybar")
  hl.exec_cmd("sleep 1 && spotify-launcher &")
end)


-- -------------------------
-- ------ EXEC RELOAD ------
-- -------------------------

-- Once reloading config these settings execute/set/apply
hl.exec_cmd("wal -s -t -i ~/wallpapers/pywallpaper.jpg && pkill -SIGUSR2 waybar")


